# ----------------------------------------------------------------------
# Library functions this node uses (from builder/fb/nodecode/*_lib.py):
# parse_now, say_date, is_business_day, next_business_day_on_or_after, count_or,
# nth_business_day_after, prev_business_day_on_or_before, deadline_for, band_for, load_products,
# to_float, money, product_facts, find_products, _m, close_reason, _line, new_state, present_text,
# _num, _days, final_say, clear_reply, publish
# ----------------------------------------------------------------------
import json

import datetime


import json


import re


WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
]


def parse_now(now):
    s = str(now or "").strip().replace(" ", "T")
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        try:
            return datetime.datetime.fromisoformat(s[:10] + "T00:00")
        except Exception:
            return None


def say_date(d):
    return WEEKDAYS[d.weekday()] + " " + str(d.day) + " " + MONTHS[d.month - 1] + " " + str(d.year)


def is_business_day(d, cfg):
    workdays = cfg.get("workdays") or [0, 1, 2, 3, 4]
    return d.weekday() in workdays and d.isoformat() not in set(cfg.get("holidays") or [])


def next_business_day_on_or_after(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d + datetime.timedelta(days=1)
    return d


def count_or(value, default):
    """A whole number >= 0 from a policy value; `default` only when it is missing (None or
    ''). 0 is a real value: `x or 1` would turn it into 1."""
    if value is None or str(value).strip() == "":
        return default
    try:
        return max(0, int(float(value)))
    except Exception:
        return default


def nth_business_day_after(today, n, cfg):
    """The Nth business day after today; N = 0 is today, or the next business day when today
    is not one (a deadline or a promise day is always a business day)."""
    if n <= 0:
        return next_business_day_on_or_after(today, cfg)
    d = today
    count = 0
    for _ in range(400):
        d = d + datetime.timedelta(days=1)
        if is_business_day(d, cfg):
            count += 1
            if count >= n:
                return d
    return d


def prev_business_day_on_or_before(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d - datetime.timedelta(days=1)
    return d


def deadline_for(today, band, cfg):
    """Band deadline: the Nth business day after today (`deadline_unit` "business", default),
    or N calendar days after today moved back to a business day ("calendar"). 0 means today
    (the next business day when today is not one); a deadline is never before today."""
    n = count_or(band.get("deadline_business_days"), None)
    if n is None:
        n = count_or(band.get("deadline_days"), 0)
    if str(band.get("deadline_unit") or "business") == "calendar":
        d = prev_business_day_on_or_before(today + datetime.timedelta(days=n), cfg)
        return d if d >= today else next_business_day_on_or_after(today, cfg)
    return nth_business_day_after(today, n, cfg)


def band_for(days_late, cfg, nearest=False):
    """The band holding `days_late`; with `nearest`, outside every band (0 days, more than the
    last band) the nearest one, so the product still gets a deadline and attempts."""
    try:
        n = int(float(days_late))
    except Exception:
        return None
    best, gap = None, None
    for b in cfg.get("bands") or []:
        lo = b.get("min_days_late")
        hi = b.get("max_days_late")
        d = max((lo - n) if lo is not None else 0, (n - hi) if hi is not None else 0, 0)
        if d == 0:
            return b
        if nearest and (gap is None or d < gap):
            best, gap = b, d
    return best


def load_products(raw, key="products"):
    """get_account products arrive as a list, a JSON string or a python repr string (or an
    object holding the list under `key`)."""
    if isinstance(raw, list):
        return [p for p in raw if isinstance(p, dict)]
    if isinstance(raw, str) and raw.strip():
        for loader in (
            json.loads,
            lambda s: json.loads(
                s.replace("'", '"')
                .replace("True", "true")
                .replace("False", "false")
                .replace("None", "null")
            ),
        ):
            try:
                v = loader(raw)
                if isinstance(v, list):
                    return [p for p in v if isinstance(p, dict)]
                if isinstance(v, dict) and isinstance(v.get(key), list):
                    return [p for p in v[key] if isinstance(p, dict)]
            except Exception:
                pass
    return []


def to_float(x):
    """1250, '1250.5', '1,250.00', '£1,250.00' -> float; raises on anything else (a European
    '1.250,00' too, it is not guessed)."""
    s = str(x).strip()
    if re.search(r"\.\d{3},", s):
        raise ValueError(s)
    return float(re.sub(r"^[£€$]|^(?:gbp|eur|usd)\s*|,(?=\d{3}\b)", "", s, flags=re.I))


def money(x):
    try:
        return "%.2f" % to_float(x)
    except Exception:
        return str(x)


def product_facts(products, now, cfg):
    dt = parse_now(now)
    today = dt.date() if dt else None
    out = {
        "product_count": str(len(products)),
        "products_state": "known" if products else "unknown",
    }
    lines = []
    # CFG["product_fields"]: the names the tool API uses for these roles (hidden briefs can
    # rename them).
    fmap = cfg.get("product_fields") or dict()

    def pf(p, role):
        return p.get(fmap.get(role) or role)

    for i, p in enumerate(products):
        k = "p" + str(i + 1)
        ptype = str(pf(p, "type") or "")
        floor_field = (cfg.get("floor_field") or {}).get(ptype, "")
        floor = p.get(floor_field) if floor_field else None
        name_tpl = (cfg.get("product_names") or {}).get(ptype) or ptype.replace("_", " ")
        try:
            spoken = name_tpl.format(**{kk: str(vv) for kk, vv in p.items()})
        except Exception:
            spoken = ptype.replace("_", " ")
        band = band_for(pf(p, "days_late"), cfg, True)
        # days late outside every band: the nearest band's rules, noted (never no deadline)
        out[k + "_band_nearest"] = "yes" if band and not band_for(pf(p, "days_late"), cfg) else ""
        deadline = ""
        attempts = ""
        if band is not None and today is not None:
            deadline = deadline_for(today, band, cfg).isoformat()
            attempts = str(band.get("attempts") if band.get("attempts") is not None else "")
        out[k + "_id"] = str(pf(p, "product_id") or "")
        out[k + "_name"] = spoken
        out[k + "_past_due"] = money(pf(p, "past_due"))
        dl = pf(p, "days_late")
        try:
            dl = str(int(float(dl))) if float(dl) == int(float(dl)) else str(dl)
        except Exception:
            dl = str(dl or "")
        out[k + "_days_late"] = dl
        out[k + "_floor"] = money(floor) if floor is not None else ""
        out[k + "_band"] = str(band.get("name")) if band else ""
        out[k + "_deadline"] = deadline
        out[k + "_attempts"] = attempts
        lines.append(
            "Product "
            + str(i + 1)
            + ": "
            + spoken
            + " (product_id "
            + out[k + "_id"]
            + "), past due "
            + out[k + "_past_due"]
            + ", "
            + out[k + "_days_late"]
            + " days late"
            + (", floor " + out[k + "_floor"] if out[k + "_floor"] else "")
            + (
                ", latest promise date "
                + deadline
                + " ("
                + say_date(datetime.date.fromisoformat(deadline))
                + ")"
                if deadline
                else ""
            )
            + (", persuasion attempts " + attempts if attempts else "")
        )
    out["product_facts"] = "\n".join(lines)
    # What the model may say about the products: no floor, deadline or attempt count, so it
    # cannot make an offer of its own.
    out["product_brief"] = "\n".join(
        out["p" + str(i + 1) + "_name"]
        + ": "
        + out["p" + str(i + 1) + "_past_due"]
        + " past due, "
        + out["p" + str(i + 1) + "_days_late"]
        + " days late"
        for i in range(len(products))
    )
    return out


_WORD_MONTHS = dict((m.lower(), i + 1) for i, m in enumerate(MONTHS))


_WORD_MONTHS.update(dict((m[:3].lower(), i + 1) for i, m in enumerate(MONTHS)))


def find_products(v, cfg=None):
    """get_account products, wherever the platform put them: the mapped variable, a
    flattened `<x>.data.<list>` key, or one flattened key per field. The list name and the
    number fields come from the config (`products_list` or `product_fields.list`;
    `product_fields`, `floor_field`), Brief A's names when it has none. Without `cfg` the
    code node's CFG is used."""
    if cfg is None:
        try:
            cfg = CFG  # noqa: F821  (defined by the code node around this library)
        except Exception:
            cfg = dict()
    if not isinstance(cfg, dict):
        cfg = dict()
    fmap = cfg.get("product_fields") or dict()
    lst = str(cfg.get("products_list") or fmap.get("list") or "products")
    tail = ".data." + lst
    for key in ["products"] + [k for k in v if str(k).endswith(tail)]:
        got = load_products(v.get(key), lst.split(".")[-1])
        if got:
            return got
    rows = {}
    rx = re.escape(tail) + r"[.\[](\d+)\]?\.(\w+)$"
    for k in list(v):
        m = re.search(rx, str(k))
        if m:
            rows.setdefault(int(m.group(1)), {})[m.group(2)] = v[k]
    money_fields = ["minimum_payment", "instalment_amount"]
    money_fields += [str(fmap.get(r) or r) for r in ("past_due", "days_late")]
    money_fields += [str(f) for f in (cfg.get("floor_field") or dict()).values() if f]
    out = []
    for i in sorted(rows):
        p = rows[i]
        for f in money_fields:
            if f in p:
                try:  # noqa: SIM105  (the sandbox's module list is not documented)
                    p[f] = to_float(p[f])
                except Exception:
                    pass
        out.append(p)
    return out


import datetime


import re


def _m(x):
    return money(x)


def close_reason(neg, sem):
    """close_call's reason for a semantic reason. `neg.reasons` holds add_note's values; when the
    brief's close_call uses other values for the same reason, `neg.close_reasons` holds those
    (review: add_note `refused`, close_call `declined_payment`)."""
    return str(
        (neg.get("close_reasons") or {}).get(sem) or (neg.get("reasons") or {}).get(sem) or sem
    )


def _line(neg, key, default=""):
    return str((neg.get("lines") or {}).get(key) or default)


def new_state(pf, neg, now):
    """pf: product_facts output (pK_* keys)."""
    n = int(pf.get("product_count") or 0)
    ps = []
    for k in range(1, n + 1):
        key = "p" + str(k)
        try:
            full = to_float(pf.get(key + "_past_due") or 0)  # '1,250.00', '£1,250.00' too
        except Exception:
            full = 0.0
        try:
            floor = to_float(pf.get(key + "_floor") or 0) or full
        except Exception:
            floor = full
        try:
            a = str(pf.get(key + "_attempts") if pf.get(key + "_attempts") is not None else "")
            att = int(a) if a.strip().isdigit() else 1  # 0 is a band with no persuasion
        except Exception:
            att = 1
        deadline = str(pf.get(key + "_deadline") or "")
        try:
            datetime.date.fromisoformat(deadline[:10])
        except Exception:
            deadline = ""
        if full <= 0.005 or not deadline or not pf.get(key + "_id"):
            # no amount, no deadline (a product outside every band) or no id: nothing about it
            # can be offered or recorded (review: a missing past_due was offered as 0.00)
            continue
        floor = min(floor, full) if floor > 0.005 else full
        ps.append(
            {
                "id": pf.get(key + "_id") or key,
                "name": pf.get(key + "_name") or "",
                "full": full,
                "floor": floor,
                "deadline": deadline,
                "days_late": pf.get(key + "_days_late") or "",
                "attempts": att,
                "used": 0,
                "too_much": False,
                "floor_offered": 0,
                "vague_asked": 0,
                "status": "open",
                "amount": None,
                "date": None,
                "offer": None,
                "own_deadline": False,
            }
        )
        if pf.get(key + "_band_nearest"):
            ps[-1]["band_nearest"] = True  # days late outside every band: the nearest one's
    st = {
        "phase": "ask_today",
        "i": 0,
        "p": ps,
        "human_asked": 0,
        "stop": 0,
        "transfer": "",
        "action": "say",
        "say": "",
        "rec": [],
        "rec_try": 0,
        "notes": [],
        "final_lines": [],
        "last_ask": "",
    }
    order = str(neg.get("product_order") or "get_account")
    for n, q in enumerate(ps):
        q["n"] = n  # get_account order, for "first_product"
    if order == "days_late_desc":
        ps.sort(key=lambda q: -_num(q.get("days_late")))
    elif order == "past_due_desc":
        ps.sort(key=lambda q: -q["full"])
    if not ps:
        # get_account failed or gave nothing usable: no negotiation on made-up values
        st["phase"] = "closing"
        st["action"] = "finish"
        st["final_lines"] = [
            _line(neg, "no_account", "I am sorry, I cannot see your account details right now.")
        ]
        st["final_outcome"] = (neg.get("outcomes") or {}).get("no_promise", "no_promise")
        st["final_reason"] = close_reason(neg, "service_error")
        return st
    st["say"] = present_text(st, neg)
    st["last_ask"] = st["say"]
    return st


def present_text(st, neg):
    """The exact words that state every late product and ask the first question."""
    lines = []
    for p in st["p"]:
        lines.append(
            "Your "
            + p["name"]
            + " has "
            + _m(p["full"])
            + " past due and is "
            + str(_days(p))
            + " days late."
        )
    multi = len(st["p"]) > 1
    q = (
        _line(neg, "multi_today_question", "Can you pay all of them today?")
        if multi
        else _line(neg, "today_question", "Can you make this payment today?")
    )
    return " ".join(
        x
        for x in [_line(neg, "present_intro", "I am calling about a late payment.")] + lines + [q]
        if x
    )


def _num(x):
    try:
        return to_float(x)
    except Exception:
        return 0.0


def _days(p):
    return p.get("days_late", "") if p.get("days_late") not in (None, "") else ""


def final_say(st, neg):
    lines = list(st.get("final_lines") or [])
    lines.append(_line(neg, "goodbye", "Thank you for your time. Goodbye."))
    return " ".join(x for x in lines if x)


REPLY_VARS = (
    "reply_kind",
    "said_date_text",
    "said_amount_text",
    "said_amount",
    "all_products",
    "about_product",
    "has_question",
)


REPLY_CLEAR = dict(reply_kind="unclear", all_products="no", about_product="none", has_question="no")


def clear_reply(v):
    for k in REPLY_VARS:
        v[k] = REPLY_CLEAR.get(k, "")


def publish(v, st, neg):
    v["neg_state"] = json.dumps(st)
    v["neg_action"] = st.get("action") or "say"
    v["neg_say"] = st.get("say") or ""
    # speak: neg_say is the exact sentence (spoken as is); llm: an instruction for the model
    v["neg_mode"] = st.get("mode") or "speak"
    v["neg_phase"] = st.get("phase") or ""
    if st.get("rec"):
        v["rec_product_id"] = str(st.get("rec_product_id") or "")
        v["rec_amount"] = st.get("rec_amount")
        v["rec_date"] = str(st.get("rec_date") or "")
    v["transfer_queue"] = str(st.get("transfer_queue") or "")
    if st.get("action") in ("finish", "transfer"):
        v["final_outcome"] = str(st.get("final_outcome") or "")
        v["final_reason"] = str(st.get("final_reason") or "")
        v["final_say"] = final_say(st, neg)
        notes = st.get("notes") or []
        v["note_count"] = str(len(notes))
        if notes:
            v["note_product_id"] = notes[0][0]
            v["note_reason"] = notes[0][1]

