# ----------------------------------------------------------------------
# Library functions this node uses (from builder/fb/nodecode/*_lib.py):
# parse_now, say_date, is_business_day, next_business_day_on_or_after, count_or,
# nth_business_day_after, prev_business_day_on_or_before, deadline_for, attempt1_date,
# last_business_day_of_week, calendar_facts, to_float, money, _pol, _m, _d, close_reason, call_ok,
# _line, _the, _finish, _transfer, _set_rec, record_result, final_say, clear_reply, publish,
# load_state, end_notes
# ----------------------------------------------------------------------
import json

import datetime


import json


import re


WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
]


def parse_now(now):
    s = str(now or "").strip().replace(" ", "T")
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        try:
            return datetime.datetime.fromisoformat(s[:10] + "T00:00")
        except Exception:
            return None


def say_date(d):
    return WEEKDAYS[d.weekday()] + " " + str(d.day) + " " + MONTHS[d.month - 1] + " " + str(d.year)


def is_business_day(d, cfg):
    workdays = cfg.get("workdays") or [0, 1, 2, 3, 4]
    return d.weekday() in workdays and d.isoformat() not in set(cfg.get("holidays") or [])


def next_business_day_on_or_after(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d + datetime.timedelta(days=1)
    return d


def count_or(value, default):
    """A whole number >= 0 from a policy value; `default` only when it is missing (None or
    ''). 0 is a real value: `x or 1` would turn it into 1."""
    if value is None or str(value).strip() == "":
        return default
    try:
        return max(0, int(float(value)))
    except Exception:
        return default


def nth_business_day_after(today, n, cfg):
    """The Nth business day after today; N = 0 is today, or the next business day when today
    is not one (a deadline or a promise day is always a business day)."""
    if n <= 0:
        return next_business_day_on_or_after(today, cfg)
    d = today
    count = 0
    for _ in range(400):
        d = d + datetime.timedelta(days=1)
        if is_business_day(d, cfg):
            count += 1
            if count >= n:
                return d
    return d


def prev_business_day_on_or_before(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d - datetime.timedelta(days=1)
    return d


def deadline_for(today, band, cfg):
    """Band deadline: the Nth business day after today (`deadline_unit` "business", default),
    or N calendar days after today moved back to a business day ("calendar"). 0 means today
    (the next business day when today is not one); a deadline is never before today."""
    n = count_or(band.get("deadline_business_days"), None)
    if n is None:
        n = count_or(band.get("deadline_days"), 0)
    if str(band.get("deadline_unit") or "business") == "calendar":
        d = prev_business_day_on_or_before(today + datetime.timedelta(days=n), cfg)
        return d if d >= today else next_business_day_on_or_after(today, cfg)
    return nth_business_day_after(today, n, cfg)


def attempt1_date(today, cfg):
    """Date of persuasion attempt 1 (CFG["attempt1"]):
    rule "last_business_day_of_week" (Brief A rule 30: this week's last business day, or next
    week's when today is that day or later), or rule "nth_business_day" with `n`."""
    a = cfg.get("attempt1") or dict()
    if str(a.get("rule") or "last_business_day_of_week") == "nth_business_day":
        return nth_business_day_after(today, count_or(a.get("n"), 1), cfg)
    this_last = last_business_day_of_week(today, cfg)
    if this_last is not None and this_last > today:
        return this_last
    return last_business_day_of_week(today + datetime.timedelta(days=7), cfg)


def last_business_day_of_week(d, cfg):
    monday = d - datetime.timedelta(days=d.weekday())
    best = None
    for i in range(7):
        day = monday + datetime.timedelta(days=i)
        if is_business_day(day, cfg):
            best = day
    return best


def calendar_facts(now, cfg):
    """Every date fact the agent needs, as strings (routing compares strings)."""
    out = {"calendar_state": "unknown"}
    dt = parse_now(now)
    if dt is None:
        return out
    today = dt.date()
    out["calendar_state"] = "known"
    out["today_iso"] = today.isoformat()
    out["today_text"] = say_date(today)
    out["now_time"] = dt.strftime("%H:%M")
    out["today_is_business_day"] = "yes" if is_business_day(today, cfg) else "no"
    this_last = last_business_day_of_week(today, cfg)
    next_last = last_business_day_of_week(today + datetime.timedelta(days=7), cfg)
    out["last_business_day_this_week"] = this_last.isoformat() if this_last else ""
    out["last_business_day_next_week"] = next_last.isoformat() if next_last else ""
    a1 = attempt1_date(today, cfg)
    out["attempt1_date"] = a1.isoformat() if a1 else ""
    out["attempt1_date_text"] = say_date(a1) if a1 else ""
    for b in cfg.get("bands") or []:
        dl = deadline_for(today, b, cfg)
        key = "deadline_" + str(b.get("name"))
        out[key] = dl.isoformat()
        out[key + "_text"] = say_date(dl)
    # Callback window (third party).
    cb = cfg.get("callback") or {}
    start = str(cb.get("start") or "10:00")
    end = str(cb.get("end") or "19:00")
    # CFG["callback"]: include_today (default true), business_days_ahead (default 1; 0 = only
    # today), business_days_only (default true: a callback day must be a business day).
    days = []
    bd_only = cb.get("business_days_only", True) is not False
    if cb.get("include_today", True) is not False and out["now_time"] < end:
        if is_business_day(today, cfg) or not bd_only:
            days.append(("today", today, max(start, out["now_time"])))
    for n in range(1, count_or(cb.get("business_days_ahead"), 1) + 1):
        nb = (
            nth_business_day_after(today, n, cfg) if bd_only else today + datetime.timedelta(days=n)
        )
        days.append(("next business day" if n == 1 else say_date(nb), nb, start))
    out["callback_window_text"] = " or ".join(
        name + " (" + say_date(d) + ", " + d.isoformat() + ") from " + s + " to " + end
        for name, d, s in days
    )
    out["callback_days"] = ",".join(d.isoformat() for _, d, _ in days)
    # A table of the coming days so the model never computes a date itself.
    monday = today - datetime.timedelta(days=today.weekday())
    rows = []
    for i in range(0, 28):
        d = today + datetime.timedelta(days=i)
        labels = []
        if i == 0:
            labels.append("today")
        if i == 1:
            labels.append("tomorrow")
        week = (d - monday).days // 7
        if week == 0:
            labels.append("this " + WEEKDAYS[d.weekday()])
        elif week == 1:
            labels.append("next " + WEEKDAYS[d.weekday()])
        status = (
            "business day"
            if is_business_day(d, cfg)
            else ("holiday" if d.isoformat() in set(cfg.get("holidays") or []) else "weekend")
        )
        rows.append(
            say_date(d)
            + " = "
            + d.isoformat()
            + " ("
            + status
            + ")"
            + (" [" + ", ".join(labels) + "]" if labels else "")
        )
    out["date_table"] = "\n".join(rows)
    return out


def to_float(x):
    """1250, '1250.5', '1,250.00', '£1,250.00' -> float; raises on anything else (a European
    '1.250,00' too, it is not guessed)."""
    s = str(x).strip()
    if re.search(r"\.\d{3},", s):
        raise ValueError(s)
    return float(re.sub(r"^[£€$]|^(?:gbp|eur|usd)\s*|,(?=\d{3}\b)", "", s, flags=re.I))


def money(x):
    try:
        return "%.2f" % to_float(x)
    except Exception:
        return str(x)


_WORD_MONTHS = dict((m.lower(), i + 1) for i, m in enumerate(MONTHS))


_WORD_MONTHS.update(dict((m[:3].lower(), i + 1) for i, m in enumerate(MONTHS)))


import datetime


import re


POLICY_DEFAULTS = {
    # A42: ask once whether you can help, transfer on the second request. 1 = transfer at once.
    "human_requests_to_transfer": 2,
    # A45: close after the customer says twice that they do not want to talk.
    "stop_requests_to_close": 2,
    # A37: create_promise calls per product before giving up (first try + one retry).
    "promise_attempts": 2,
    # A37/B11 after the last failed call: "continue" (mark failed, close/note service_error)
    # or "transfer" (transfer to queue `record_failure_queue`).
    "record_failure": "continue",
    "record_failure_queue": "support",
    # A32: "offer_support" (offer a transfer; yes -> transfer, no -> hardship),
    # "transfer" (transfer at once) or "close" (no persuasion, close as hardship).
    "hardship": "offer_support",
    "hardship_queue": "support",
    # B closing: no promise recorded -> reason of the "first_product" (get_account order)
    # whose status is not paid, or the first status of `reason_priority` that any product has.
    "no_promise_reason": "first_product",
    "reason_priority": ["dispute", "hardship", "service_error", "refused"],
    # B10: add_note calls on a transferred call.
    "notes_on_transfer": False,
    # A21: times to ask for the exact day after a vague period, before proposing the deadline.
    "vague_date_asks": 1,
    # A26/A27: times the floor is offered after "too much" or an amount below the floor.
    "floor_offers": 1,
}


def _pol(neg, key):
    val = neg.get(key)
    return POLICY_DEFAULTS[key] if val is None else val


def _m(x):
    return money(x)


def _d(iso):
    return say_date(datetime.date.fromisoformat(iso)) if iso else ""


def close_reason(neg, sem):
    """close_call's reason for a semantic reason. `neg.reasons` holds add_note's values; when the
    brief's close_call uses other values for the same reason, `neg.close_reasons` holds those
    (review: add_note `refused`, close_call `declined_payment`)."""
    return str(
        (neg.get("close_reasons") or {}).get(sem) or (neg.get("reasons") or {}).get(sem) or sem
    )


def call_ok(value, mode="flag"):
    """Did a write succeed, from the response field the workflow mapped. "flag": a true/false
    field (ok); "present": a field only a success returns (promise_id); "no_error": an error
    field, empty on success. A tool API without an ok field must not read as failed every
    time (review: create_promise answering only promise_id)."""
    v = str(value if value is not None else "").strip().lower()
    if mode == "present":
        return v not in ("", "false", "none", "null", "0")
    if mode == "no_error":
        return v in ("", "none", "null", "false")
    return v == "true"


def _line(neg, key, default=""):
    return str((neg.get("lines") or {}).get(key) or default)


def _the(name):
    """'the personal loan', but 'your overdraft' stays as it is."""
    n = str(name or "")
    low = n.lower()
    if low.startswith(("the ", "your ", "my ", "a ", "an ")):
        return n
    return "the " + n


def _finish(st, neg):
    st["action"] = "finish"
    oc = neg.get("outcomes") or {}
    rs = neg.get("reasons") or {}
    sem = {
        "refused": "refused",
        "open": "refused",
        "hardship": "hardship",
        "dispute": "dispute",
        "failed": "service_error",
        "paid": "paid",
    }
    recorded = set(st.get("recorded") or [])
    for q in st["p"]:
        if q["id"] in recorded:
            q["status"] = "recorded"  # a promise the bank holds is never undone by later words
    what = st.get("transfer") or ""
    # notes on a transfer (Northwind 4.8 "also when the call is transferred"): a product still
    # open takes the transfer's code when it is a note code too (add_note's enum is the reasons'
    # values; Northwind has none for a plan or a person), else its own (refused)
    tr = (neg.get("transfer_reasons") or {}).get(what)
    xfer = rs.get(what) or (tr if tr in rs.values() else None)
    notes = []
    for q in st["p"]:
        if q["status"] != "recorded":
            s = sem.get(q["status"], "refused")
            notes.append([q["id"], xfer if xfer and q["status"] == "open" else rs.get(s, s)])
    st["notes"] = notes if neg.get("notes") else []
    if st["transfer"]:
        st["final_outcome"] = oc.get("transferred", "transferred")
        st["final_reason"] = (neg.get("transfer_reasons") or {}).get(st["transfer"], st["transfer"])
        if not _pol(neg, "notes_on_transfer"):
            st["notes"] = []
        return
    if any(q["status"] == "recorded" for q in st["p"]):
        st["final_outcome"] = oc.get("promise", "promise")
        st["final_reason"] = ""
        return
    by_account = sorted(st["p"], key=lambda q: q.get("n", 0))
    left = [sem.get(q["status"], "refused") for q in by_account if q["status"] != "paid"]
    if not left:
        st["final_outcome"] = oc.get("paid", "paid")
        # only a brief whose outcome table gives "already paid" a reason sets close_reasons.paid
        st["final_reason"] = str((neg.get("close_reasons") or {}).get("paid") or "")
        return
    st["final_outcome"] = oc.get("no_promise", "no_promise")
    s = left[0]
    if _pol(neg, "no_promise_reason") == "priority":
        s = next((x for x in _pol(neg, "reason_priority") if x in left), left[0])
    st["final_reason"] = close_reason(neg, s)


def _transfer(st, what, neg, open_as="open"):
    st["transfer"] = what
    st["transfer_queue"] = (neg.get("queues") or {}).get(what, what)
    # Brief B rule 10: agreed but unrecorded promises are dropped. A hardship transfer: every
    # product still open is a hardship one (its note, when notes are written on a transfer).
    for q in st["p"]:
        if q["status"] in ("agreed", "open"):
            q["status"] = open_as
    st["final_lines"].append(
        _line(neg, "transfer_" + what, "I am connecting you with a colleague now.")
    )
    _finish(st, neg)
    st["action"] = "transfer"


def _set_rec(st):
    if st["rec"]:
        q = st["p"][st["rec"][0]]
        st["rec_product_id"] = q["id"]
        st["rec_amount"] = q["amount"]
        st["rec_date"] = q["date"]


def record_result(st, ok, neg, cal):
    """After one create_promise call. Retries up to `promise_attempts` calls in total, then
    marks the product failed (and transfers when `record_failure` says so)."""
    j = st["rec"][0]
    q = st["p"][j]
    if ok:
        q["status"] = "recorded"
        st["recorded"] = list(st.get("recorded") or []) + [q["id"]]
        st["rec"].pop(0)
        st["rec_try"] = 0
    else:
        st["rec_try"] += 1
        if st["rec_try"] >= int(_pol(neg, "promise_attempts")):
            q["status"] = "failed"
            st["rec"].pop(0)
            st["rec_try"] = 0
            if _pol(neg, "record_failure") == "transfer":
                st["rec"] = []
                _transfer(st, _pol(neg, "record_failure_queue"), neg)
                return st
    if st["rec"]:
        st["action"] = "record"
        _set_rec(st)
        return st
    # this read-back's products only: one recorded earlier in the call was said then
    batch = st.get("rec_batch")
    rec = [q for q in st["p"] if q["status"] == "recorded" and (batch is None or q["id"] in batch)]
    bad = [q for q in st["p"] if q["status"] == "failed" and (batch is None or q["id"] in batch)]
    parts = []
    if rec:
        parts.append(
            "Your promise is recorded: "
            + "; ".join(
                _the(q["name"]) + ", " + _m(q["amount"]) + " on " + _d(q["date"]) for q in rec
            )
            + ". "
            + _line(neg, "recorded", "You will receive a text message confirming this promise.")
        )
    if bad:
        parts.append(
            "I could not record the promise for " + ", ".join(_the(q["name"]) for q in bad) + "."
        )
    anything = _line(neg, "anything_else", "Is there anything else I can help you with?")
    parts.append(anything)
    st["action"] = "say"
    st["mode"] = "speak"
    st["phase"] = "closing"
    st["say"] = " ".join(parts)
    st["last_ask"] = anything
    return st


def final_say(st, neg):
    lines = list(st.get("final_lines") or [])
    lines.append(_line(neg, "goodbye", "Thank you for your time. Goodbye."))
    return " ".join(x for x in lines if x)


REPLY_VARS = (
    "reply_kind",
    "said_date_text",
    "said_amount_text",
    "said_amount",
    "all_products",
    "about_product",
    "has_question",
)


REPLY_CLEAR = dict(reply_kind="unclear", all_products="no", about_product="none", has_question="no")


def clear_reply(v):
    for k in REPLY_VARS:
        v[k] = REPLY_CLEAR.get(k, "")


def publish(v, st, neg):
    v["neg_state"] = json.dumps(st)
    v["neg_action"] = st.get("action") or "say"
    v["neg_say"] = st.get("say") or ""
    # speak: neg_say is the exact sentence (spoken as is); llm: an instruction for the model
    v["neg_mode"] = st.get("mode") or "speak"
    v["neg_phase"] = st.get("phase") or ""
    if st.get("rec"):
        v["rec_product_id"] = str(st.get("rec_product_id") or "")
        v["rec_amount"] = st.get("rec_amount")
        v["rec_date"] = str(st.get("rec_date") or "")
    v["transfer_queue"] = str(st.get("transfer_queue") or "")
    if st.get("action") in ("finish", "transfer"):
        v["final_outcome"] = str(st.get("final_outcome") or "")
        v["final_reason"] = str(st.get("final_reason") or "")
        v["final_say"] = final_say(st, neg)
        notes = st.get("notes") or []
        v["note_count"] = str(len(notes))
        if notes:
            v["note_product_id"] = notes[0][0]
            v["note_reason"] = notes[0][1]


def load_state(v):
    try:
        st = json.loads(v.get("neg_state") or "")
        return st if isinstance(st, dict) else None
    except Exception:
        return None


def end_notes(v, st, neg, held):
    """A call our side ends (an error, a transfer that did not happen): with notes on, every
    product without a promise (ids not in `held`) gets its note, as _finish writes them; one
    still being talked about is a service_error. Sets the note_* variables."""
    rs = neg.get("reasons") or {}
    ks = ("refused", "hardship", "dispute", "paid")
    ps = sorted([q for q in st.get("p") or [] if isinstance(q, dict)], key=lambda q: q.get("n", 0))
    notes = [
        [q.get("id"), rs.get(s, s)]
        for q in ps
        if q.get("id") not in held
        for s in [q.get("status") if q.get("status") in ks else "service_error"]
    ]
    notes = notes if neg.get("notes") else []
    st["notes"] = notes
    v["neg_state"] = json.dumps(st)
    v["note_count"] = str(len(notes))
    if notes:
        v["note_product_id"], v["note_reason"] = notes[0]

